exercise.referenceSolution:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

int main(void) {
    Node *head = NULL, *tail = NULL;
    int size = 0;
    char command[8];
    while (scanf("%7s", command) == 1) {
        if (strcmp(command, "enqueue") == 0) {
            int x;
            if (scanf("%d", &x) != 1) {
                break;
            }
            Node *node = malloc(sizeof *node);
            if (node == NULL) {
                return 1;
            }
            node->value = x;
            node->next = NULL;
            if (tail == NULL) {
                head = node;
            } else {
                tail->next = node;
            }
            tail = node;
            size++;
        } else if (strcmp(command, "dequeue") == 0 || strcmp(command, "front") == 0) {
            if (head == NULL) {
                printf("пусто\n");
                continue;
            }
            printf("%d\n", head->value);
            if (command[0] == 'd') {
                Node *node = head;
                head = node->next;
                if (head == NULL) {
                    tail = NULL;
                }
                free(node);
                size--;
            }
        } else if (strcmp(command, "size") == 0) {
            printf("%d\n", size);
        }
    }
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}

