#include <stdio.h>

static int left[1000], queue[1000];

int main(void) {
    int n, q;
    if (scanf("%d %d", &n, &q) != 2 || n < 1 || n > 1000 || q < 1) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%d", &left[i]);
        queue[i] = i;
    }
    int head = 0, size = n;
    long long time = 0, switches = 0;
    while (size > 0) {
        int p = queue[head];
        head = (head + 1) % n;
        size--;
        switches++;
        int run = left[p] < q ? left[p] : q;
        time += run;
        left[p] -= run;
        if (left[p] == 0) {
            printf("процесс %d: момент %lld\n", p + 1, time);
        } else {
            queue[(head + size) % n] = p;
            size++;
        }
    }
    printf("переключений: %lld\n", switches);
    return 0;
}

